const {test}=require('node:test');
const assert=require('node:assert/strict');
const {ttlMillis,isReserved}=require('../src/reservations.cjs');
test('production and staging preserve reservation duration',()=>{
 for(const config of [require('../config/production.json'),require('../config/staging.json')]){
  assert.equal(ttlMillis(config.reservationTtl),90000);assert.equal(isReserved(1000,1100,config),true);
  assert.equal(isReserved(1000,90999,config),true);assert.equal(isReserved(1000,91000,config),false);
 }
 assert.equal(ttlMillis('2m'),120000);assert.equal(ttlMillis('125ms'),125);assert.equal(ttlMillis(1),1);
});
test('invalid or overflowing TTL fails before use',()=>{
 for(const value of [undefined,null,'','90','90s junk','1.5s','0s','-1s','1h',0,-1,1.5,Infinity,NaN,'9007199254740991m'])assert.throws(()=>ttlMillis(value));
});

exports.ttlMillis = function(value) {
  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value) || value <= 0) throw new Error('invalid reservation TTL');
    return value;
  }
  const match = typeof value === 'string' && /^([0-9]+)(ms|s|m)$/.exec(value);
  if (!match) throw new Error('invalid reservation TTL');
  const ttl = BigInt(match[1]) * ({ms:1n,s:1000n,m:60000n}[match[2]]);
  if (ttl <= 0n || ttl > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error('invalid reservation TTL');
  return Number(ttl);
};
exports.isReserved = (createdAt, now, config) => now - createdAt < exports.ttlMillis(config.reservationTtl);

function identity(value) {
  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value) || value < 0) throw new Error('invalid identity');
    return String(value);
  }
  if (typeof value !== 'string' || !/^[0-9]+$/.test(value)) throw new Error('invalid identity');
  return BigInt(value).toString();
}
exports.reconcile = function(state, event) {
  if (!event) throw new Error('invalid identity');
  const key = identity(event.tenantId) + ':' + identity(event.orderId);
  if (!state || !Array.isArray(state.seen)) throw new Error('invalid state');
  if (state.seen.includes(key)) return { applied: false, key };
  state.seen.push(key);
  return { applied: true, key };
};

exports.place = async function(order, reservations) {
  if (!order || typeof order.id !== 'string' || !order.id || typeof order.currency !== 'string' || !/^[A-Z]{3}$/.test(order.currency)) throw new Error('invalid order');
  if (typeof order.total !== 'string' || !/^[0-9]+(?:\.[0-9]{1,2})?$/.test(order.total)) throw new Error('invalid total');
  const [whole, fraction = ''] = order.total.split('.');
  const cents = BigInt(whole) * 100n + BigInt(fraction.padEnd(2, '0'));
  if (cents > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error('invalid total');
  return reservations({ orderId: order.id, amountCents: Number(cents), currency: order.currency });
};

exports.quoteCancellation = function(booking, minutesToDeparture) {
  if (!booking || booking.status !== 'CONFIRMED' || typeof booking.refundable !== 'boolean' || !Number.isSafeInteger(booking.paidCents) || booking.paidCents < 0 || typeof minutesToDeparture !== 'number' || !Number.isFinite(minutesToDeparture) || minutesToDeparture < 0) throw new Error('invalid cancellation quotation');
  const refundCents = !booking.refundable ? 0 : minutesToDeparture >= 2880 ? booking.paidCents : minutesToDeparture >= 1440 ? Math.floor(booking.paidCents / 2) : 0;
  return { refundCents, retainedCents: booking.paidCents - refundCents };
};

package com.lumen.money;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class LedgerAmountTest {
 @Test void respectsCurrencyScaleAndHalfUpTies() {
  assertEquals(1005L, LedgerAmount.minorUnits(new BigDecimal("1.005"),"KWD"));
  assertEquals(1L, LedgerAmount.minorUnits(new BigDecimal("1.4"),"JPY"));
  assertEquals(2L, LedgerAmount.minorUnits(new BigDecimal("1.5"),"JPY"));
  assertEquals(101L, LedgerAmount.minorUnits(new BigDecimal("1.005"),"USD"));
  assertEquals(101L, LedgerAmount.minorUnits(new BigDecimal("1.005"),"EUR"));
  assertEquals(0L, LedgerAmount.minorUnits(BigDecimal.ZERO,"KWD"));
 }
 @Test void preservesLongBoundaryAndRejectsOverflowAndInvalidInputs() {
  assertEquals(Long.MAX_VALUE,LedgerAmount.minorUnits(new BigDecimal("92233720368547758.07"),"USD"));
  assertEquals(Long.MAX_VALUE,LedgerAmount.minorUnits(new BigDecimal("9223372036854775.807"),"KWD"));
  assertThrows(ArithmeticException.class,()->LedgerAmount.minorUnits(new BigDecimal("92233720368547758.075"),"USD"));
  assertThrows(IllegalArgumentException.class,()->LedgerAmount.minorUnits(new BigDecimal("-0.001"),"KWD"));
  assertThrows(IllegalArgumentException.class,()->LedgerAmount.minorUnits(BigDecimal.ONE,"XXX"));
  assertThrows(IllegalArgumentException.class,()->LedgerAmount.minorUnits(null,"EUR"));
 }
}

const {test}=require('node:test');
const assert=require('node:assert/strict');
const path=require('node:path');
const {release}=require('../src/release.cjs');
const {withCaseDatabases}=require(process.env.DT_CHALLENGE_PG_HARNESS);
const fresh=fn=>withCaseDatabases(path.resolve(__dirname,'..'),fn);
async function snapshot({orders,billing}){return {orders:Array.from(await orders.unsafe('select tenant_id::text,id::text,account_id::text,status,amount::text from sales.orders order by tenant_id,id')),accounts:Array.from(await orders.unsafe('select tenant_id::text,id::text,enabled from sales.accounts order by tenant_id,id')),risk:Array.from(await billing.unsafe('select tenant_id::text,id::text,status,credit_limit::text from risk.accounts order by tenant_id,id')),payments:Array.from(await billing.unsafe('select tenant_id::text,order_id::text,status,amount::text from pay.payments order by tenant_id,order_id'))};}
async function assertOnlySelectedReleased(db){const before=await snapshot(db);const expected=structuredClone(before);expected.orders.find(x=>x.tenant_id==='22').status='RELEASED';expected.payments.find(x=>x.tenant_id==='22').status='CAPTURED';assert.deepEqual(await release(db,'22','420'),{tenantId:'22',orderId:'420',amount:'100.000001',status:'RELEASED'});assert.deepEqual(await snapshot(db),expected);const after=await snapshot(db);await assert.rejects(release(db,'22','420'));assert.deepEqual(await snapshot(db),after);}
test('own credit releases selected tenant despite blocked neighbor; retry has no writes',()=>fresh(assertOnlySelectedReleased));
test('approved neighbor cannot be captured by another tenant release',()=>fresh(async db=>{await db.billing.unsafe("update risk.accounts set status='APPROVED' where tenant_id=11");await assertOnlySelectedReleased(db);}));
test('exact credit boundary succeeds without changing decimal amounts',()=>fresh(async db=>{await db.billing.unsafe("update risk.accounts set credit_limit=100.000001 where tenant_id=22");await assertOnlySelectedReleased(db);}));
test('every business rejection preserves all four tables in both databases',async()=>{
 const mutations=[['orders',"update sales.orders set status='NEW' where tenant_id=22"],['orders',"update sales.accounts set enabled=false where tenant_id=22"],['billing',"update risk.accounts set status='BLOCKED' where tenant_id=22"],['billing',"update risk.accounts set credit_limit=100.000000 where tenant_id=22"],['billing',"update pay.payments set status='CANCELLED' where tenant_id=22"],['billing',"update pay.payments set amount=100.000002 where tenant_id=22"],['billing',"delete from risk.accounts where tenant_id=22"],['billing',"delete from pay.payments where tenant_id=22"]];
 for(const [dbName,sql] of mutations)await fresh(async db=>{await db[dbName].unsafe(sql);const before=await snapshot(db);await assert.rejects(release(db,'22','420'));assert.deepEqual(await snapshot(db),before);});
 await fresh(async db=>{const before=await snapshot(db);await assert.rejects(release(db,'22','999'));assert.deepEqual(await snapshot(db),before);});
});
